import logging

class ExtraEndstop:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.extras_es = {}
        self.extras_pe = {}
        self.section = config.get_name()
        self._use_extra_flag = False
        self._old_name = None
        self._extra_name = None
        self._align_z = [
         0.0, 0.0]
        self._label = "xyz"
        for axis in self._label:
            endstop = "extra_" + axis + "_endstop_pin"
            pos_endstop = "extra_" + axis + "_position_endstop"
            if config.has_section(self.section):
                pos = config.getfloat(pos_endstop)
                pin = config.get(endstop)
                if pin != "None":
                    self.extras_es[axis + "e"] = pin
                    self.extras_pe[axis + "e"] = pos
                zpe = 0.0

        for ze in self.extras_pe.keys():
            if ze == "ze":
                zpe = self.extras_pe[ze]
                break
            self._zpe = {
              'configed': zpe, 'offset': 0.0, 'diff': 0.0, 'flushed': False}

    def get_extra_es(self, name):
        """
        use for config
        """
        if len(self.extras_es) < 1:
            return
        for n in self.extras_es.keys():
            en = name + "e"
            if en == n:
                return self.extras_es[n]

    def has_es(self, axis):
        if len(self.extras_es) < 1:
            return False
        for name in self.extras_es.keys():
            if axis in name:
                return True
            return False

    def open(self):
        self._use_extra_flag = True

    def close(self):
        self._use_extra_flag = False

    def opened(self):
        return self._use_extra_flag

    def config_extra(self, axis_list):
        if not self._use_extra_flag:
            self._extra_name = None
            return
        for num in axis_list:
            self._extra_name = self._label[num] + "e"

    def endstops(self, es_list):
        if len(self.extras_es) < 1:
            return es_list
        for (es, n) in es_list:
            if not self._extra_name is not None:
                if self._extra_name == n:
                    self._extra_name = None
                    return [
                     (
                      es, n)]
                return [
                 es_list[0]]

    def config_extra_position(self, name, pos):
        self.extras_pe[name] = pos

    def get_position_endstop(self, name):
        if not self._use_extra_flag:
            if name not in self.extras_pe:
                only_label = name[0]
                return self.extras_pe[only_label]
            return self.extras_pe[name]
        en = name + "e"
        if en in self.extras_pe:
            return self.extras_pe[en]
        return self.extras_pe[name]

    def get_verified_offset(self):
        return self._zpe["offset"]

    def set_verified_offset(self, offset):
        self._zpe["offset"] += offset
        self._zpe["flushed"] = True

    def flush_zpe(self):
        for zpe in self.extras_pe.keys():
            if zpe == "ze":
                if self._zpe["flushed"]:
                    self.extras_pe[zpe] = self._zpe["configed"] - self._zpe["offset"]
                    self._zpe["flushed"] = False


def load_config(config):
    return ExtraEndstop(config)

